async function save(){guard();if(boundaryDirty)throw Error('Önce çizdiğiniz parça sınırını kaydedin.');const validated=validateStudio(plan,data.session,data.photos,{demo});if(demo){plan=validated;dirty=false;tell('Örnek hazırlık doğrulandı. Bu sekmenin belleğinde tutuluyor.');}else{data=await api.rpc('k360_save_studio',{session_id:data.session.id,expected_revision:data.session.revision,payload:validated});plan=structuredClone(data.session.studio);dirty=false;stale=false;tell('Sunum hazırlığı iş emrine kaydedildi.');}render();}
